contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint a1, uint a2) public payable {
        require(a1 > 0);
        require(a2 > 0);
        require(address(this).balance >= a1 + a2);
        // First cycle: deposit a1 and withdraw it all, clearing credit.
        c.deposit{value: a1}();
        c.withdrawAll();
        // Baseline after the first cycle.
        uint before = address(this).balance;
        uint cBefore = address(c).balance;
        // Second cycle: a fresh deposit of a2 must be fully withdrawable.
        c.deposit{value: a2}();
        assert(address(c).balance == cBefore + a2);
        c.withdrawAll();
        // Rule: after the cycle reset, the second withdrawAll delivers exactly a2,
        // restoring the test contract's balance and c's balance to their pre-deposit values.
        assert(address(this).balance == before && address(c).balance == cBefore);
    }
    receive() external payable {}
}

